window.EditableMathsPilot=Object.assign(window.EditableMathsPilot||{},{"WV-MATHS-APPLICATIONS-2021-ASSUMED-Q14":{"question":"<p>Patrick invests $717850 from 1 January at 5.7% p.a., compounded monthly. He withdraws $4500 at each month’s end plus $4000 at each year’s end.</p>","parts":[{"label":"(a)(i)","text":"<p>Identify this type of investment.</p>","marks":1,"lines":4,"space":"lines","diagram":""},{"label":"(a)(ii)","text":"<p>Determine the balance at the end of year one.</p>","marks":4,"lines":12,"space":"lines","diagram":""},{"label":"(a)(iii)","text":"<p>Determine the balance at the end of year two.</p>","marks":3,"lines":9,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Instead he could set up a perpetuity at the same interest rate. Calculate the quarterly payments.</p>","marks":3,"lines":9,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)(i)</td><td>An annuity.</td><td>1</td></tr><tr><td>(a)(ii)</td><td>With j = 0.057/12, uses 717850(1+j)<sup>12</sup> − 4500[(1+j)<sup>12</sup>−1]/j, then subtracts the extra $4000. Award for rate, annuity calculation, annual withdrawal and final balance $700420.20.</td><td>4</td></tr><tr><td>(a)(iii)</td><td>Applies 12 further monthly withdrawals to the year-one balance and subtracts another $4000. Balance ≈ $681970.53. Award for starting balance, recurrence and result.</td><td>3</td></tr><tr><td>(b)</td><td>Effective quarterly rate = (1 + 0.057/12)<sup>3</sup> − 1; payment = 717850 times this rate ≈ $10278.03. Award for equivalent rate, perpetuity calculation and result.</td><td>3</td></tr></tbody></table>","diagram":"","marks":11,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-METHODS-2021-FREE-Q06":{"question":"<p>Three normal distributions A, B and C and a separate normal density for X are graphed.</p>","parts":[{"label":"(a)(i)","text":"<p>What is the mean of A?</p>","marks":1,"lines":4,"space":"lines","diagram":""},{"label":"(a)(ii)","text":"<p>Which distribution has the largest standard deviation? Justify.</p>","marks":1,"lines":4,"space":"lines","diagram":""},{"label":"(b)(i)","text":"<p>Shade the area corresponding to P(6 ≤ X ≤ 9).</p>","marks":1,"lines":4,"space":"lines","diagram":""},{"label":"(b)(ii)","text":"<p>Is P(6 ≤ X ≤ 9) ≥ 0.5? Justify.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(c)","text":"<p>Y satisfies P(Y ≥ 2) &gt; P(Y &gt; 2). Could Y be normal or binomial? Explain.</p>","marks":2,"lines":6,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)(i)</td><td>Mean = 2.</td><td>1</td></tr><tr><td>(a)(ii)</td><td>C, since it has the widest spread/lowest peak.</td><td>1</td></tr><tr><td>(b)(i)</td><td>Shades under the density between x = 6 and x = 9.</td><td>1</td></tr><tr><td>(b)(ii)</td><td>No. The shaded interval has width3 and density everywhere below0.14, so its area is below0.42, hence below0.5.</td><td>2</td></tr><tr><td>(c)</td><td>Not normal, because a continuous variable has P(Y = 2) = 0.</td><td>1</td></tr><tr><td>(c)</td><td>It may be binomial: a discrete variable may have positive probability at 2.</td><td>1</td></tr></tbody></table>","diagram":"<img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\"><img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\">","marks":7,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-SPECIALIST-2020-ASSUMED-Q20":{"question":"<p>Square OACB has OA = a, OB = b. Points P,Q,R,S satisfy OP = ka, AQ = kb, RC = ka and SB = kb, 0 ≤ k ≤ 1.</p>","parts":[{"label":"(a)","text":"<p>Use vectors to prove angle PQR is 90°.</p>","marks":5,"lines":15,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Now OA = 10 cm and OP increases at 0.2 cm/second. Let x = OP. Find the rate of change of the area of square PQRS when x = 3 cm.</p>","marks":4,"lines":12,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>QP = (k−1)a − kb; QR = −ka + (1−k)b. Their dot product is −k(k−1)|a|<sup>2</sup> − k(1−k)|b|<sup>2</sup> = 0, since a·b=0 and |a|=|b|. Thus the nonzero sides are perpendicular. Award for both vectors, dot product, square properties and conclusion.</td><td>5</td></tr><tr><td>(b)</td><td>Area = x<sup>2</sup> + (10−x)<sup>2</sup>. Hence dA/dt = (4x−20)dx/dt = (12−20)(0.2) = −1.6 cm<sup>2</sup>/second, a decrease. Award for area, derivative, chain rule and result.</td><td>4</td></tr></tbody></table>","diagram":"<img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\">","marks":9,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-APPLICATIONS-2018-ASSUMED-Q17":{"question":"<p>A pipe network with capacities in L/min and three cuts is shown in Diagram 1. Diagram 2 shows a possible flow.</p>","parts":[{"label":"(a)","text":"<p>State the capacities of Cuts 1, 2 and 3.</p>","marks":3,"lines":9,"space":"lines","diagram":""},{"label":"(b)(i)","text":"<p>Explain why x = 30.</p>","marks":1,"lines":4,"space":"lines","diagram":""},{"label":"(b)(ii)","text":"<p>Calculate y and z.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(c)","text":"<p>State which pipes are at full capacity in Diagram 2.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(d)","text":"<p>State the flow value in Diagram 2.</p>","marks":1,"lines":4,"space":"lines","diagram":""},{"label":"(e)(i)","text":"<p>List a route allowing another 2 L/min.</p>","marks":1,"lines":4,"space":"lines","diagram":""},{"label":"(e)(ii)","text":"<p>Show the increased flow is a maximum.</p>","marks":1,"lines":4,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>Cut 1 = 55, Cut 2 = 62, Cut 3 = 61 L/min; one mark each.</td><td>3</td></tr><tr><td>(b)(i)</td><td>Flow conservation at B gives x = 5 + 13 + 12 = 30.</td><td>1</td></tr><tr><td>(b)(ii)</td><td>y = 8; z = 22. One mark each.</td><td>2</td></tr><tr><td>(c)</td><td>Pipes DT, ET, BE and DC are at capacity; award for the complete set under the source rubric.</td><td>2</td></tr><tr><td>(d)</td><td>Flow = 48 L/min.</td><td>1</td></tr><tr><td>(e)(i)</td><td>Route S–B–C–T carries the extra 2 L/min.</td><td>1</td></tr><tr><td>(e)(ii)</td><td>New flow 50 L/min equals the minimum cut, so it is maximal.</td><td>1</td></tr></tbody></table>","diagram":"<img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\"><img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\">","marks":11,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-APPLICATIONS-2020-ASSUMED-Q11":{"question":"<p>Shari borrows $325000, paying $700 twice monthly at equal intervals. Interest is calculated daily. Option 1: 2.55% p.a. for year one, then 2.99% for years two and three. Option 2: 2.85% fixed for all three years.</p>","parts":[{"label":"(a)","text":"<p>Explain the benefit of two $700 payments over a single $1400 month-end payment.</p>","marks":1,"lines":4,"space":"lines","diagram":""},{"label":"(b)(i)","text":"<p>For Option 1 calculate the balance after year one.</p>","marks":3,"lines":9,"space":"lines","diagram":""},{"label":"(b)(ii)","text":"<p>For Option 1 calculate the balance after year three.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(c)","text":"<p>Which option is better after three years, and by how much?</p>","marks":3,"lines":9,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>The earlier payment reduces principal sooner and therefore reduces interest.</td><td>1</td></tr><tr><td>(b)(i)</td><td>Uses equivalent half-monthly rate (1+0.0255/365)<sup>365/24</sup>−1, 24 payments of $700, and initial balance $325000. Balance ≈ $316386.79; award for rate, calculation and result.</td><td>3</td></tr><tr><td>(b)(ii)</td><td>Uses rate (1+0.0299/365)<sup>365/24</sup>−1 for 48 further payments from year-one balance, giving ≈ $301279.68.</td><td>2</td></tr><tr><td>(c)</td><td>Option 2 balance uses its daily-equivalent rate for 72 payments and is ≈ $301422.81. Option 1 is lower by ≈ $143.12. Award for calculation, comparison and difference.</td><td>3</td></tr></tbody></table>","diagram":"","marks":9,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-SPECIALIST-2023-FREE-Q04":{"question":"<p>The graphs of f and g are shown.</p>","parts":[{"label":"(a)","text":"<p>Sketch y = g<sup>−1</sup>(x).</p>","marks":2,"lines":8,"space":"drawing","diagram":""},{"label":"(b)","text":"<p>State g(f<sup>−1</sup>(0)).</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(c)","text":"<p>Determine the x-values for which f(g(x)) is defined.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(d)","text":"<p>Sketch y = f(−|x|).</p>","marks":2,"lines":8,"space":"drawing","diagram":""},{"label":"(e)","text":"<p>|x + 1| = k − |x + a| has infinitely many solutions, exactly −3 ≤ x ≤ −1. Find a and k.</p>","marks":3,"lines":9,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>Reflects all points of g in y=x, preserving open/closed endpoints. Its inverse relation includes a vertical segment and is not a function.</td><td>2</td></tr><tr><td>(b)</td><td>f<sup>−1</sup>(0)=−1, hence g(−1)=3.</td><td>2</td></tr><tr><td>(c)</td><td>Requires g(x) in the domain of f, giving 1 ≤ x ≤ 3.</td><td>2</td></tr><tr><td>(d)</td><td>Keeps the left-hand branch of f and reflects it to the right, giving the symmetric W shape with zeros at ±1 and the correct endpoint restrictions.</td><td>2</td></tr><tr><td>(e)</td><td>The sum |x+1|+|x+a| is constant between its two vertices. Vertices −3 and −1 give a=3; their distance gives k=2. Award for geometry, a and k.</td><td>3</td></tr></tbody></table>","diagram":"<img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\"><img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\"><img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\">","marks":11,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-METHODS-2018-ASSUMED-Q11":{"question":"<p>Ava’s drone flies north then south at a constant height of 5 m. At t=0 it is directly above her. Its signed northward velocity is v(t)=2sin(t/3+π/6) m/second for 0 ≤ t ≤ 16.</p>","parts":[{"label":"(a)","text":"<p>Determine displacement x(t), given x(0)=0.</p>","marks":3,"lines":9,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Where is the drone relative to Ava at 16 seconds?</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(c)","text":"<p>When heading south and decelerating at 0.5 m/second<sup>2</sup>, how far has it travelled since t=0?</p>","marks":3,"lines":9,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>Integrates x=−6cos(t/3+π/6)+C; x(0)=0 gives C=3√3. Award for antiderivative, initial condition and rule.</td><td>3</td></tr><tr><td>(b)</td><td>x(16)≈−0.267 m: about 0.267 m south of Ava and 5 m above ground.</td><td>2</td></tr><tr><td>(c)</td><td>Solves a(t)=(2/3)cos(t/3+π/6)=0.5 on the southward branch, after the first turn at t=5π/2. Splits the distance integral at that turning time; total distance ≈21.696 m. Award for time selection, distance method and result.</td><td>3</td></tr></tbody></table>","diagram":"","marks":8,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-METHODS-2023-ASSUMED-Q07":{"question":"<p>A birdwatcher observes 200 birds at a favourite national-park location one morning; 76 are Carnaby’s Black Cockatoos. Let p be the park’s true proportion of these birds.</p>","parts":[{"label":"(a)","text":"<p>Find a point estimate for p.</p>","marks":1,"lines":4,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Find a 95% confidence interval.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(c)","text":"<p>Find the minimum sample size ensuring margin of error at most 0.02 at 95% confidence.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(d)","text":"<p>Identify and explain two sampling biases.</p>","marks":4,"lines":12,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>p̂=76/200=0.38.</td><td>1</td></tr><tr><td>(b)</td><td>Uses 0.38 ± 1.96√(0.38×0.62/200), giving approximately (0.3127,0.4473).</td><td>2</td></tr><tr><td>(c)</td><td>Uses the worst-case p=0.5: n≥1.96<sup>2</sup>(0.25)/0.02<sup>2</sup>=2401.</td><td>2</td></tr><tr><td>(d)</td><td>Location bias: a favourite spot may have a different species mix from the whole park.</td><td>2</td></tr><tr><td>(d)</td><td>Time bias: observing on one morning may overrepresent birds active then. Other well-explained valid biases accepted.</td><td>2</td></tr></tbody></table>","diagram":"","marks":9,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-SPECIALIST-2016-FREE-Q08":{"question":"<p>The graph f(x)=(x−1)<sup>2</sup>−4 is shown.</p>","parts":[{"label":"(a)","text":"<p>Sketch y=1/f(x).</p>","marks":4,"lines":12,"space":"drawing","diagram":""},{"label":"(b)","text":"<p>Sketch y=f(|x|).</p>","marks":2,"lines":8,"space":"drawing","diagram":""},{"label":"(c)","text":"<p>Restrict f to x≤k so that its inverse is a function, using the largest such domain. State k and explain.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(d)","text":"<p>Determine the inverse rule and its domain under that restriction.</p>","marks":3,"lines":9,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>Asymptotes x=−1 and x=3, y=0; central stationary point (1,−¼); y-intercept (0,−⅓); correct positive outer and negative central branches. Award one for each source feature group.</td><td>4</td></tr><tr><td>(b)</td><td>Keeps x≥0 branch and reflects it in y-axis, producing minima at (±1,−4) and central point (0,−3).</td><td>2</td></tr><tr><td>(c)</td><td>k=1, the vertex abscissa; the left branch is one-to-one on x≤1.</td><td>2</td></tr><tr><td>(d)</td><td>Interchanges variables and uses the negative square root: f<sup>−1</sup>(x)=1−√(x+4), domain x≥−4. Award for rearrangement, branch and domain.</td><td>3</td></tr></tbody></table>","diagram":"<img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\"><img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\"><img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\">","marks":11,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-SPECIALIST-2023-ASSUMED-Q15":{"question":"<p>A sample of n personal loans gives a 99% confidence interval 10.2&lt;μ&lt;25.4, in thousands of dollars.</p>","parts":[{"label":"(a)","text":"<p>Find the sample mean.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Find the standard deviation of the sample mean.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(c)","text":"<p>Ali says everyone is 99% certain the true mean lies in this particular interval. Give two reasons this is incorrect.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(d)","text":"<p>The true sample size was 2n and its mean $2000 larger. Recalculate the 99% interval.</p>","marks":3,"lines":9,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>Midpoint (10.2+25.4)/2=17.8 thousand dollars.</td><td>2</td></tr><tr><td>(b)</td><td>Margin 7.6=z×SE, so SE≈7.6/2.576≈2.950 thousand dollars.</td><td>2</td></tr><tr><td>(c)</td><td>The fixed population mean either is or is not in this realised interval.</td><td>1</td></tr><tr><td>(c)</td><td>99% confidence describes long-run coverage of the method, not a personal certainty for everyone or a probability assigned to the fixed mean.</td><td>1</td></tr><tr><td>(d)</td><td>New mean 19.8; standard error is divided by √2, so new margin is 7.6/√2. Interval ≈(14.426,25.174) thousand dollars. Award for mean, error and bounds.</td><td>3</td></tr></tbody></table>","diagram":"","marks":9,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-METHODS-2023-FREE-Q04":{"question":"<p>A website with S weekly visits has rank R=2log₁₀(S/S₀), where S₀ is a fixed reference visit count.</p>","parts":[{"label":"(a)","text":"<p>Find the rank for 100 times the reference visits.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Rank 12 corresponds to 1.5×10<sup>9</sup> visits/week. Find S₀.</p>","marks":3,"lines":9,"space":"lines","diagram":""},{"label":"(c)","text":"<p>Using the supplied log₁₀ graph, estimate weekly visits for rank 3.2.</p>","marks":3,"lines":9,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>R=2log₁₀100=4; substitution and value.</td><td>2</td></tr><tr><td>(b)</td><td>12=2log₁₀(1.5×10<sup>9</sup>/S₀); ratio=10<sup>6</sup>; S₀=1500. One mark per step.</td><td>3</td></tr><tr><td>(c)</td><td>log₁₀(S/1500)=1.6. Reads ratio about 40, hence S≈60000 (exact model about59716) visits/week. Award for rearrangement, graph reading and scaling.</td><td>3</td></tr></tbody></table>","diagram":"<img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\">","marks":8,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-METHODS-2019-ASSUMED-Q13":{"question":"<p>About 40% of working adults miss breakfast on weekdays. A random sample has 400 working adults.</p>","parts":[{"label":"(a)(i)","text":"<p>State the approximate distribution of the sample proportion.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(a)(ii)","text":"<p>Find the probability this proportion exceeds 44%.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Tom samples the first 400 workers he meets in a Perth city mall at lunchtime. Explain two biases.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(c)(i)","text":"<p>Amir suggests a random sample of 400 voters contacted by telephone. State a possible bias.</p>","marks":1,"lines":4,"space":"lines","diagram":""},{"label":"(c)(ii)","text":"<p>Which method is better? Give a reason.</p>","marks":1,"lines":4,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)(i)</td><td>Approximately normal, mean0.4 and variance0.4×0.6/400=0.0006.</td><td>2</td></tr><tr><td>(a)(ii)</td><td>Standardises (0.44−0.4)/√0.0006; upper-tail probability≈0.0512.</td><td>2</td></tr><tr><td>(b)</td><td>City/mall location may differ from the working population; lunchtime excludes workers unavailable then. One mark per explained source.</td><td>2</td></tr><tr><td>(c)(i)</td><td>Voters/telephone respondents may exclude working non-voters or people without reachable phones.</td><td>1</td></tr><tr><td>(c)(ii)</td><td>Amir’s random selection generally has broader coverage; accepts a justified comparison.</td><td>1</td></tr></tbody></table>","diagram":"","marks":8,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-APPLICATIONS-2019-ASSUMED-Q10":{"question":"<p>Ruby Ducks had15 stores at the end of1992,22579 at the end of2017 and30256 at the end of2018. Its model is Tₙ=1.34Tₙ₋₁, T₁=15.</p>","parts":[{"label":"(a)","text":"<p>Show the common ratio is about1.34.</p>","marks":1,"lines":4,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Write the nth-term rule.</p>","marks":1,"lines":4,"space":"lines","diagram":""},{"label":"(c)","text":"<p>Find the first year with more than200000 stores.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(d)","text":"<p>Each store employs12 people daily, earning $114.80 each. Find total daily wages at the beginning of2012.</p>","marks":3,"lines":9,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>30256/22579≈1.34.</td><td>1</td></tr><tr><td>(b)</td><td>Tₙ=15(1.34)<sup>n−1</sup>.</td><td>1</td></tr><tr><td>(c)</td><td>Solves15(1.34)<sup>n−1</sup>&gt;200000; first n=34, year2025.</td><td>2</td></tr><tr><td>(d)</td><td>Beginning2012 uses end2011, n=20. Model gives about3900 stores; 12×114.8×15(1.34)<sup>19</sup>≈$5372860.47/day. Award for year, store count and wage calculation.</td><td>3</td></tr></tbody></table>","diagram":"","marks":7,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-METHODS-2023-ASSUMED-Q08":{"question":"<p>An oscillating mass has v(t)=2t cos(t+π/2) m/second, t≥0. Its velocity graph has the shaded signed area shown.</p>","parts":[{"label":"(a)","text":"<p>Find the first two positive direction-change times exactly.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Interpret the signed shaded area.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(c)","text":"<p>Give a distance integral from t=π/3 to4π/3.</p>","marks":3,"lines":9,"space":"lines","diagram":""},{"label":"(d)","text":"<p>Find the first time after π with zero acceleration.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(e)","text":"<p>If x(t)=A sin(t+π/2)+B cos(t+π/2)+2t sin(t+π/2), find A,B.</p>","marks":3,"lines":9,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>t=π and2π; velocity changes sign at both.</td><td>2</td></tr><tr><td>(b)</td><td>Net displacement, in metres, over the shaded time interval; signed area adds displacement above and below the axis.</td><td>2</td></tr><tr><td>(c)</td><td>Distance=−∫<sub>π/3</sub><sup>π</sup>2t cos(t+π/2)dt+∫<sub>π</sub><sup>4π/3</sup>2t cos(t+π/2)dt. Award for signs, turning point and integrand.</td><td>3</td></tr><tr><td>(d)</td><td>a=−2sin t−2t cos t; solves sin t+t cos t=0, first root afterπ≈4.913 seconds.</td><td>2</td></tr><tr><td>(e)</td><td>Differentiate the proposed x, match coefficients with v: A=0, B=2. Award for differentiation and both constants.</td><td>3</td></tr></tbody></table>","diagram":"<img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\">","marks":12,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-METHODS-2016-ASSUMED-Q14":{"question":"<p>A loaded five-sided die is rolled60 times. Its frequencies for1,2,3,4,5 are5,15,15,20,5 respectively, as graphed.</p>","parts":[{"label":"(a)","text":"<p>Find the simulated proportion of prime outcomes.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Find mean and standard deviation of the sample prime proportion over60 rolls, using these results.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(c)","text":"<p>Which confidence level,90% or95%, gives the smaller margin? State that margin.</p>","marks":3,"lines":9,"space":"lines","diagram":""},{"label":"(d)","text":"<p>The60-roll experiment is repeated200 times and sample proportions graphed. Describe key features.</p>","marks":2,"lines":6,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>Prime faces2,3,5 occur35 times; p̂=35/60=7/12.</td><td>2</td></tr><tr><td>(b)</td><td>Mean≈7/12; SD=√[(7/12)(5/12)/60]≈0.06365.</td><td>2</td></tr><tr><td>(c)</td><td>90% has smaller z and margin; E≈1.645×0.06365≈0.1047. Award for level, reason and error.</td><td>3</td></tr><tr><td>(d)</td><td>Approximately bell-shaped/normal and centred near7/12, with spread consistent with the standard error.</td><td>2</td></tr></tbody></table>","diagram":"<img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\">","marks":9,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-METHODS-2021-ASSUMED-Q08":{"question":"<p>Carrot weight W is normal with mean142.8g and SD30.6g. Classes: small W≤110, medium110&lt;W≤155, large155&lt;W≤210, extra-large W&gt;210. Given medium probability0.5131 and large0.3310.</p><table><tr><th>Class</th><th>Small</th><th>Medium</th><th>Large</th><th>Extra large</th></tr><tr><td>Weight(g)</td><td>W≤110</td><td>110&lt;W≤155</td><td>155&lt;W≤210</td><td>W&gt;210</td></tr><tr><td>Probability</td><td></td><td>0.5131</td><td>0.3310</td><td></td></tr></table>","parts":[{"label":"(a)","text":"<p>Find the percentage weighing more than155g.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Find missing small and extra-large probabilities.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(c)","text":"<p>Among non-medium carrots, what proportion is small?</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(d)","text":"<p>A bag has12 randomly selected carrots. Find the probability of at most two small carrots.</p>","marks":3,"lines":9,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>Normal upper tail at z=(155−142.8)/30.6 gives≈34.51%.</td><td>2</td></tr><tr><td>(b)</td><td>Small≈0.1419; extra-large≈0.0140; one mark each.</td><td>2</td></tr><tr><td>(c)</td><td>0.1419/(1−0.5131)≈0.2914.</td><td>2</td></tr><tr><td>(d)</td><td>X~Bin(12,0.1419); sums P(X=0,1,2), giving≈0.7634. Award for model, event and probability.</td><td>3</td></tr></tbody></table>","diagram":"","marks":9,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-METHODS-2017-ASSUMED-Q18":{"question":"<p>A random sample of320 bees includes15 sleepy lullabees.</p>","parts":[{"label":"(a)","text":"<p>Find the sample proportion.</p>","marks":1,"lines":4,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Find a90% confidence interval to four decimals.</p>","marks":3,"lines":9,"space":"lines","diagram":""},{"label":"(c)","text":"<p>Find its margin of error.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(d)(i)","text":"<p>The true proportion is0.02. A new sample has290 bees. Find P(p̂≤0.03).</p>","marks":3,"lines":9,"space":"lines","diagram":""},{"label":"(d)(ii)","text":"<p>Would a larger sample increase or decrease this probability? Explain.</p>","marks":2,"lines":6,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>15/320=0.046875.</td><td>1</td></tr><tr><td>(b)</td><td>Uses z=1.645 and √[p̂(1−p̂)/320]; interval≈(0.0274,0.0663). Award for z, calculation and bounds.</td><td>3</td></tr><tr><td>(c)</td><td>E≈0.01944, or1.944 percentage points.</td><td>2</td></tr><tr><td>(d)(i)</td><td>X~Bin(290,0.02); X/290≤0.03 means X≤8. Exact probability≈0.8693; normal approximation≈0.888 is accepted by the source method. Award for model, event and calculation.</td><td>3</td></tr><tr><td>(d)(ii)</td><td>Increases: standard error shrinks and0.03 lies above the true mean0.02.</td><td>2</td></tr></tbody></table>","diagram":"","marks":11,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-METHODS-2023-ASSUMED-Q06":{"question":"<p>A bee colony has B(t)=4e<sup>1.4t</sup> thousand bees, t years since establishment.</p>","parts":[{"label":"(a)","text":"<p>Find initial population.</p>","marks":1,"lines":4,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Find the first-six-month increase.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(c)","text":"<p>Find growth rate at two years.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(d)","text":"<p>When is growth rate65000 bees/year?</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(e)","text":"<p>After three years population declines as b(s)=Ae<sup>rs</sup> thousand bees, s years since decline begins. One year later there are100000 bees. Find A,r.</p>","marks":4,"lines":12,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>4000 bees.</td><td>1</td></tr><tr><td>(b)</td><td>4000(e<sup>0.7</sup>−1)≈4055 bees.</td><td>2</td></tr><tr><td>(c)</td><td>B′=5.6e<sup>1.4t</sup> thousand/year; at2 gives≈92090 bees/year.</td><td>2</td></tr><tr><td>(d)</td><td>5.6e<sup>1.4t</sup>=65 gives t≈1.751 years.</td><td>2</td></tr><tr><td>(e)</td><td>A=4e<sup>4.2</sup>≈266.745; 100=Ae<sup>r</sup>, so r=ln(100/A)≈−0.981124. Award for continuity, A, equation and r.</td><td>4</td></tr></tbody></table>","diagram":"","marks":11,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-METHODS-2022-ASSUMED-Q08":{"question":"<p>Weekly petrol demand X, in units of10000 litres, has density f(x)=5(1−x)<sup>4</sup>,0≤x≤1.</p>","parts":[{"label":"(a)","text":"<p>Find expected demand and variance with appropriate units.</p>","marks":4,"lines":12,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Find capacity giving a1% chance of running out, to the nearest litre.</p>","marks":3,"lines":9,"space":"lines","diagram":""},{"label":"(c)","text":"<p>Petrol level rises at h′(t)=5/(2t+3) m/min. Find tank height if it takes20minutes to fill from empty.</p>","marks":3,"lines":9,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>E(X)=∫xf(x)dx=1/6; Var(X)=E(X²)−E(X)²=5/252. Mean=1666.67litres; variance=(5/252)×10000²≈1984126.98litres². Award for both moment calculations and both units/scalings.</td><td>4</td></tr><tr><td>(b)</td><td>P(X&gt;k)=(1−k)<sup>5</sup>=0.01, so k=1−0.01<sup>1/5</sup>≈0.601893; capacity≈6019litres. Award for tail equation, root and conversion.</td><td>3</td></tr><tr><td>(c)</td><td>Height=∫<sub>0</sub><sup>20</sup>5/(2t+3)dt=(5/2)ln(43/3)≈6.656m. Award for integral, antiderivative and value.</td><td>3</td></tr></tbody></table>","diagram":"<img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\">","marks":10,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-METHODS-2019-ASSUMED-Q16":{"question":"<p>A cylinder contains20 complete spherical decorations. Each sphere’s diameter is one-third of the cylinder’s internal diameter. Internal cylinder diameter plus height is42cm.</p>","parts":[{"label":"(a)","text":"<p>Show unused volume V(r)=2π[21r²−(121/81)r³], where r is internal radius.</p>","marks":3,"lines":9,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Use calculus to find dimensions maximising unused space, to the nearest millimetre.</p>","marks":4,"lines":12,"space":"lines","diagram":""},{"label":"(c)","text":"<p>Can more than20 decorations fit? Verify by calculation.</p>","marks":3,"lines":9,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>h=42−2r; cylinder volume=πr²h; subtract20(4π/3)(r/3)³ to obtain the stated formula. One mark per stage.</td><td>3</td></tr><tr><td>(b)</td><td>V′=2π[42r−(121/27)r²]; positive stationary radius r=1134/121≈9.372cm, h≈23.256cm. V″ is negative there. Rounded radius94mm and height233mm (diameter187mm). Award for derivative, stationary value, maximum and dimensions.</td><td>4</td></tr><tr><td>(c)</td><td>Unused volume at the optimum is about3863cm³, versus about128cm³ per decoration. A geometric packing check can also place at least21 spheres; there is room for additional decorations. Award for sphere size, space comparison and conclusion.</td><td>3</td></tr></tbody></table>","diagram":"<img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\">","marks":10,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-APPLICATIONS-2019-ASSUMED-Q17":{"question":"<p>Joel, aged60, has $350000 invested at6.5% p.a., compounded monthly. He contributes7.5% of his $101000 annual salary plus a $355 monthly overseas pension.</p>","parts":[{"label":"(a)","text":"<p>Find total monthly contribution.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Find his lump sum on retiring at67.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(c)","text":"<p>He uses the lump sum for a20-year annuity at7% p.a., compounded monthly. Find maximum monthly income.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(d)","text":"<p>Alternatively find monthly income from a7.5% p.a. perpetuity compounded monthly.</p>","marks":2,"lines":6,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>0.075×101000/12+355=$986.25.</td><td>2</td></tr><tr><td>(b)</td><td>84monthly contributions at j=0.065/12 give350000(1+j)<sup>84</sup>+986.25[(1+j)<sup>84</sup>−1]/j≈$655539.45.</td><td>2</td></tr><tr><td>(c)</td><td>R=655539.45(0.07/12)/[1−(1+0.07/12)<sup>−240</sup>]≈$5082.39/month.</td><td>2</td></tr><tr><td>(d)</td><td>Income=655539.45×0.075/12≈$4097.12/month.</td><td>2</td></tr></tbody></table>","diagram":"","marks":8,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-APPLICATIONS-2018-ASSUMED-Q12":{"question":"<p>A service manager compares moving averages for the time-series data in the table.</p><table><tr><th>t</th><th>Customers</th><th>3-point MA</th><th>4-point centred MA</th><th>5-point MA</th><th>6-point centred MA</th></tr><tr><td>1</td><td>840</td><td></td><td></td><td></td><td></td></tr><tr><td>2</td><td>927</td><td>901</td><td></td><td></td><td></td></tr><tr><td>3</td><td>936</td><td>919</td><td>902.625</td><td>892.8</td><td></td></tr><tr><td>4</td><td>894</td><td>899</td><td>893.625</td><td>890.4</td><td>C</td></tr><tr><td>5</td><td>867</td><td>863</td><td>879</td><td>888.6</td><td>895</td></tr><tr><td>6</td><td>828</td><td>871</td><td>880.875</td><td>886.8</td><td>890.25</td></tr><tr><td>7</td><td>918</td><td>891</td><td>886.5</td><td>883.8</td><td>882</td></tr><tr><td>8</td><td>927</td><td>908</td><td>891</td><td>B</td><td>874.5</td></tr><tr><td>9</td><td>879</td><td>886</td><td>881.625</td><td>879</td><td>877</td></tr><tr><td>10</td><td>852</td><td>850</td><td>866.625</td><td>876.6</td><td>883.75</td></tr><tr><td>11</td><td>819</td><td>859</td><td>869.25</td><td>875.4</td><td>878.75</td></tr><tr><td>12</td><td>906</td><td>882</td><td>876</td><td>872.4</td><td>869.75</td></tr><tr><td>13</td><td>921</td><td>897</td><td>879.375</td><td>868.8</td><td>863</td></tr><tr><td>14</td><td>864</td><td>873</td><td>870</td><td>868.2</td><td></td></tr><tr><td>15</td><td>834</td><td>838</td><td></td><td></td><td></td></tr><tr><td>16</td><td>A</td><td></td><td></td><td></td><td></td></tr></table>","parts":[{"label":"(a)","text":"<p>What is the purpose of moving averages?</p>","marks":1,"lines":4,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Determine the missing values A,B,C.</p>","marks":3,"lines":9,"space":"lines","diagram":""},{"label":"(c)","text":"<p>Which of the displayed moving averages is most appropriate? Justify.</p>","marks":2,"lines":6,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>Smooths short-term fluctuation to reveal the trend.</td><td>1</td></tr><tr><td>(b)</td><td>A=816, B=880.8, C=888.5; one mark each.</td><td>3</td></tr><tr><td>(c)</td><td>The5-point moving average is most appropriate because the data have a5-period cycle; it reveals a steadily decreasing trend.</td><td>2</td></tr></tbody></table>","diagram":"","marks":6,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-APPLICATIONS-2022-ASSUMED-Q10":{"question":"<p>The island cycle-track network has edge lengths in units of100metres.</p>","parts":[{"label":"(a)","text":"<p>Can every track be checked using an Eulerian trail? Justify.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(b)(i)","text":"<p>Name a route starting and ending at C that visits every rubbish-bin location.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(b)(ii)","text":"<p>State the shortest such route and its length.</p>","marks":3,"lines":9,"space":"lines","diagram":""},{"label":"(c)","text":"<p>Find the shortest G-to-C route when AG is closed, and its length.</p>","marks":2,"lines":6,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>Yes: the connected network has no odd-degree vertices, so an Eulerian circuit exists.</td><td>2</td></tr><tr><td>(b)(i)</td><td>A Hamiltonian cycle, if each location is visited once before returning to C.</td><td>2</td></tr><tr><td>(b)(ii)</td><td>C–B–A–G–H–F–E–D–C has total47units=4700m. Award for route, sum and units.</td><td>3</td></tr><tr><td>(c)</td><td>G–F–B–C, length19units=1900m.</td><td>2</td></tr></tbody></table>","diagram":"<img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\">","marks":9,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-METHODS-2023-ASSUMED-Q10":{"question":"<p>Arch-shaped fingerprints occur in5% of people. The sample-proportion distribution for samples of36 is graphed.</p>","parts":[{"label":"(a)","text":"<p>Is a normal approximation appropriate for these samples? Justify.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(b)","text":"<p>For a random sample of500, find the probability more than30 have arch-shaped fingerprints.</p>","marks":3,"lines":9,"space":"lines","diagram":""},{"label":"(c)","text":"<p>Use approximate normality to find P(p̂&gt;0.06) for samples of500.</p>","marks":2,"lines":6,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>No: the distribution is strongly right-skewed, and np=1.8 is too small.</td><td>2</td></tr><tr><td>(b)</td><td>X~Bin(500,0.05); P(X&gt;30)=P(X≥31)≈0.1309. Award for model, event and value.</td><td>3</td></tr><tr><td>(c)</td><td>p̂≈N(0.05,0.05×0.95/500); upper tail above0.06≈0.1525.</td><td>2</td></tr></tbody></table>","diagram":"<img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\">","marks":7,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-APPLICATIONS-2020-ASSUMED-Q08":{"question":"<p>A lake has660adult fish at the beginning of2020 and grows9% per month. Public fishing begins at the start of the month following the first attainment of4000fish.</p>","parts":[{"label":"(a)","text":"<p>Write a month-end recurrence.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Give the nth-term rule.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(c)","text":"<p>How many months after the beginning of2020 does fishing commence?</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(d)","text":"<p>How many fish may be taken monthly to maintain a steady population then?</p>","marks":3,"lines":9,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>T₀=660, Tₙ₊₁=1.09Tₙ.</td><td>2</td></tr><tr><td>(b)</td><td>Tₙ=660(1.09)<sup>n</sup>.</td><td>2</td></tr><tr><td>(c)</td><td>Solves660(1.09)<sup>n</sup>≥4000; first integer n=21, so fishing begins21months after the start.</td><td>2</td></tr><tr><td>(d)</td><td>T₂₁≈4031. Population replacement is0.09T₂₁≈362.8fish/month; about362whole fish may be removed without reducing the starting population. Award for population, steady-state equation and whole-fish conclusion.</td><td>3</td></tr></tbody></table>","diagram":"","marks":9,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-SPECIALIST-2024-ASSUMED-Q13":{"question":"<p>Brumby population t years after a ban in2000 is P(t)=18000/[10.25e<sup>−0.15t</sup>+1], initially1600.</p>","parts":[{"label":"(a)","text":"<p>When does population triple?</p>","marks":1,"lines":4,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Find the long-run population.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(c)","text":"<p>If P′=(1/r)P(k−P), determine r,k.</p>","marks":3,"lines":9,"space":"lines","diagram":""},{"label":"(d)","text":"<p>Find maximum population growth rate.</p>","marks":2,"lines":6,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>SolvesP=4800: t≈8.77years.</td><td>1</td></tr><tr><td>(b)</td><td>As t→∞, exponential→0; limit18000.</td><td>2</td></tr><tr><td>(c)</td><td>Logistic derivative P′=0.15P(1−P/18000), so k=18000 and r=120000. Award for derivative/model match and constants.</td><td>3</td></tr><tr><td>(d)</td><td>Maximum occurs at P=9000 and is0.15×18000/4=675brumbies/year.</td><td>2</td></tr></tbody></table>","diagram":"","marks":8,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-METHODS-2020-FREE-Q04":{"question":"<p>Plant mature heights are shown in the relative-frequency histogram. Hedge heights h metres have density d(h)=(h−1)/5 for1≤h≤2, kh² for2&lt;h≤4, and0 otherwise.</p>","parts":[{"label":"(a)","text":"<p>Find the probability a plant is at most30cm.</p>","marks":1,"lines":4,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Given height at least32cm, find the probability it exceeds38cm.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(c)","text":"<p>What percentage of hedges mature below2m?</p>","marks":3,"lines":9,"space":"lines","diagram":""},{"label":"(d)","text":"<p>Determine k.</p>","marks":3,"lines":9,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>Adds the bars below30cm:0.04+0.08=0.12.</td><td>1</td></tr><tr><td>(b)</td><td>Uses upper-tail area divided by area at least32cm, giving0.02/0.56=1/28.</td><td>2</td></tr><tr><td>(c)</td><td>∫<sub>1</sub><sup>2</sup>(h−1)/5 dh=1/10; hence10%. Award for integral, evaluation and percentage.</td><td>3</td></tr><tr><td>(d)</td><td>Total probability1 gives0.1+k∫<sub>2</sub><sup>4</sup>h²dh=1. Thus k(56/3)=0.9, so k=27/560. Award for normalisation, integral and result.</td><td>3</td></tr></tbody></table>","diagram":"<img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\">","marks":9,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-METHODS-2024-ASSUMED-Q15":{"question":"<p>Earthquake magnitude M<sub>w</sub> is plotted against log₁₀(M₀), where seismic moment M₀ is in Nm.</p>","parts":[{"label":"(a)","text":"<p>Use the graph to estimate M<sub>w</sub> for M₀=3.16×10<sup>13</sup>, showing your graph reading.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Find a,b in M<sub>w</sub>=a log₁₀(M₀)+b.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(c)","text":"<p>Express the rule as M<sub>w</sub>=a log₁₀(M₀/c).</p>","marks":3,"lines":9,"space":"lines","diagram":""},{"label":"(d)","text":"<p>Find M₀ when M<sub>w</sub>=4.</p>","marks":2,"lines":6,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>log₁₀M₀≈13.5; graph gives M<sub>w</sub>≈3.0, with guides shown.</td><td>2</td></tr><tr><td>(b)</td><td>Slope a=2/3; intercept b=−6.</td><td>2</td></tr><tr><td>(c)</td><td>Writes−6=−(2/3)×9; combines logarithms to get M<sub>w</sub>=(2/3)log₁₀(M₀/10<sup>9</sup>), so c=10<sup>9</sup>. Award for log conversion, combination and c.</td><td>3</td></tr><tr><td>(d)</td><td>4=(2/3)log₁₀(M₀/10<sup>9</sup>) gives M₀=10<sup>15</sup>Nm.</td><td>2</td></tr></tbody></table>","diagram":"<img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\">","marks":9,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-APPLICATIONS-2017-ASSUMED-Q16":{"question":"<p>A river has200crocodiles. Each year7.5% are lost and20introduced. The model is Tₙ₊₁=0.925Tₙ+b, T₁=200.</p>","parts":[{"label":"(a)(i)","text":"<p>Interpret0.925.</p>","marks":1,"lines":4,"space":"lines","diagram":""},{"label":"(a)(ii)","text":"<p>State b.</p>","marks":1,"lines":4,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Plot Tₙ for n=5,10,15,20,25,30.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(c)","text":"<p>Describe population change from your graph.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(d)","text":"<p>Find the long-run population, nearest whole animal.</p>","marks":2,"lines":6,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)(i)</td><td>92.5% of the previous year’s population remains.</td><td>1</td></tr><tr><td>(a)(ii)</td><td>b=20.</td><td>1</td></tr><tr><td>(b)</td><td>Uses Tₙ=800/3−(200/3)(0.925)<sup>n−1</sup> and correctly plots all six points; award for computation and graph.</td><td>2</td></tr><tr><td>(c)</td><td>Population increases, with progressively smaller annual increases, approaching a limit.</td><td>2</td></tr><tr><td>(d)</td><td>Fixed point L=0.925L+20 gives L=266⅔≈267crocodiles.</td><td>2</td></tr></tbody></table>","diagram":"<img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\">","marks":8,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-APPLICATIONS-2020-ASSUMED-Q16":{"question":"<p>A building project has activities A,B,C,D,E,F,G,H taking2,4,5,3,6,3,8,2days. Immediate predecessors are: A none; B none; C A,B; D B; E C; F C; G D; H D,F.</p>","parts":[{"label":"(a)","text":"<p>Complete the project network with activities and durations.</p>","marks":3,"lines":9,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Find all critical activities and the minimum duration.</p>","marks":3,"lines":9,"space":"lines","diagram":""},{"label":"(c)","text":"<p>Find floats of all non-critical activities.</p>","marks":3,"lines":9,"space":"lines","diagram":""},{"label":"(d)","text":"<p>What happens if H is delayed3days?</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(e)","text":"<p>One of B,E,F may be shortened1day. Which should be chosen and why?</p>","marks":3,"lines":9,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>Adds D3,E6,F3 with correct dependencies and completes the network; award for labels, durations and connections.</td><td>3</td></tr><tr><td>(b)</td><td>Critical paths B–C–E and B–D–G; critical activities B,C,D,E,G; minimum15days.</td><td>3</td></tr><tr><td>(c)</td><td>A float2days; F float1day; H float1day.</td><td>3</td></tr><tr><td>(d)</td><td>New duration17days; critical path B–C–F–H.</td><td>2</td></tr><tr><td>(e)</td><td>Shorten B: it lies on both original critical paths, reducing duration to14days. Shortening E alone leaves B–D–G at15; F was non-critical. Award for choice, new duration and comparison.</td><td>3</td></tr></tbody></table>","diagram":"<img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\">","marks":14,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-APPLICATIONS-2018-ASSUMED-Q08":{"question":"<p>Anthony and Bryan each invest$4500 for4years. Anthony earns3.24%p.a., compounded quarterly.</p><table><tr><th>Quarter</th><th>1</th><th>2</th><th>3</th><th>…</th><th>16</th></tr><tr><td>Value($)</td><td>4536.45</td><td></td><td></td><td>…</td><td>5120.00</td></tr></table>","parts":[{"label":"(a)(i)","text":"<p>Find Anthony’s balances after quarters2and3.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(a)(ii)","text":"<p>State his recursive investment rule.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Bryan compounds daily and reaches the same4-year balance. Explain and calculate the nominal annual rate he needs.</p>","marks":3,"lines":9,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)(i)</td><td>$4573.20 and$4610.24, respectively.</td><td>2</td></tr><tr><td>(a)(ii)</td><td>T₀=4500; Tₙ₊₁=1.0081Tₙ.</td><td>2</td></tr><tr><td>(b)</td><td>Sets(1+r/365)<sup>1460</sup>=(1+0.0324/4)<sup>16</sup>; r=365[(1.0081)<sup>4/365</sup>−1]≈0.03227. Daily compounding requires a slightly lower nominal rate, about3.227%p.a. Award for equivalent-growth equation, rate and explanation.</td><td>3</td></tr></tbody></table>","diagram":"","marks":7,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-APPLICATIONS-2022-ASSUMED-Q09":{"question":"<p>A penguin colony starts at1200. The source describes a14%annual decline but in(a) asks for the weekly model1200(0.86)<sup>n</sup>. After8weeks, predator control produces6%weekly growth.</p>","parts":[{"label":"(a)","text":"<p>Explain the proposed model for population after n weeks.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Give the recurrence for growth after predator control.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(c)","text":"<p>How many weeks of recovery return it to1200?</p>","marks":1,"lines":4,"space":"lines","diagram":""},{"label":"(d)","text":"<p>Later support gives Pₙ₊₁=−0.25Pₙ+3000, P₀=1200. Describe long-run behaviour.</p>","marks":2,"lines":6,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>The displayed model retains86%each week. If14%is annual, the weekly retention must instead be0.86<sup>1/52</sup>; the source accepts this consistent interpretation. Award for retention and repeated multiplication.</td><td>2</td></tr><tr><td>(b)</td><td>Under the stated weekly model, Q₀=1200(0.86)<sup>8</sup>≈359.06 and Qₙ₊₁=1.06Qₙ.</td><td>2</td></tr><tr><td>(c)</td><td>21weeks of recovery under the weekly model;1week under the annual-rate interpretation.</td><td>1</td></tr><tr><td>(d)</td><td>Converges to fixed point2400, alternating above and below it because the multiplier is negative with magnitude less than1.</td><td>2</td></tr></tbody></table>","diagram":"","marks":7,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-APPLICATIONS-2022-ASSUMED-Q08":{"question":"<p>Yash compares savings: Option1 earns3.05%p.a. monthly; Option2 earns3.01%p.a. daily. A third option earns3.5%p.a. daily, starting with$12300 and weekly deposits of$300. He needs$30000 in12months.</p>","parts":[{"label":"(a)","text":"<p>Which of the first two options gives the better return? Justify mathematically.</p>","marks":3,"lines":9,"space":"lines","diagram":""},{"label":"(b)(i)","text":"<p>Show the third option falls short and calculate the shortfall.</p>","marks":4,"lines":12,"space":"lines","diagram":""},{"label":"(b)(ii)","text":"<p>Find the required weekly deposit to reach$30000.</p>","marks":2,"lines":6,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>Compares effective annual rates(1+0.0305/12)<sup>12</sup>−1≈3.093% and(1+0.0301/365)<sup>365</sup>−1≈3.056%; Option1 is better. Award for both rates and comparison.</td><td>3</td></tr><tr><td>(b)(i)</td><td>Uses equivalent weekly j=(1+0.035/365)<sup>365/52</sup>−1. Future value12300(1+j)<sup>52</sup>+300[(1+j)<sup>52</sup>−1]/j≈$28608.96; shortfall$1391.04. Award for rate, periods, FV and shortfall.</td><td>4</td></tr><tr><td>(b)(ii)</td><td>Solves the same future-value equation for the contribution: approximately$326.30weekly, rounding up to meet the target.</td><td>2</td></tr></tbody></table>","diagram":"","marks":9,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-APPLICATIONS-2019-ASSUMED-Q16":{"question":"<p>Eight cities have(altitude A, latitude L, January mean maximum T): (15,31.95,25),(20,43.53,20),(24,42.88,18),(314,45.03,16),(8,6.18,28),(154,12.05,26),(37,12.46,29),(8,34.60,25). Given T=−0.022A+24.97 and r<sub>AT</sub>=−0.50.</p>","parts":[{"label":"(a)","text":"<p>Find and interpret the altitude coefficient of determination.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Find the regression of T on L and its correlation.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(c)","text":"<p>Predict Rio’s T using both lines for latitude22.93°S and altitude9m. Which is more valid? Explain.</p>","marks":3,"lines":9,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>r²=0.25: about25%of variation in T is explained by the linear relationship with altitude.</td><td>2</td></tr><tr><td>(b)</td><td>T≈−0.264476L+30.9351; r≈−0.882743.</td><td>2</td></tr><tr><td>(c)</td><td>Altitude predicts24.772°C; latitude predicts≈24.871°C. Latitude is more reliable because its correlation has greater magnitude. Award for each prediction and justified choice.</td><td>3</td></tr></tbody></table>","diagram":"","marks":7,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-SPECIALIST-2016-ASSUMED-Q15":{"question":"<p>An open4m-long triangular-prism tank has a right isosceles triangular end with equal sides1m. It starts full and leaks0.08m³/hour. Let water depth be h metres after t hours.</p>","parts":[{"label":"(a)","text":"<p>Show V(h)=4h².</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Find dh/dt at h=0.6, to0.01m/hour.</p>","marks":3,"lines":9,"space":"lines","diagram":""},{"label":"(c)","text":"<p>Show dh/dt=−1/(100h).</p>","marks":1,"lines":4,"space":"lines","diagram":""},{"label":"(d)","text":"<p>Determine h as a function of t.</p>","marks":4,"lines":12,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>Width at depth h is2h, so area=½(2h)h=h²; times length4 gives V=4h².</td><td>2</td></tr><tr><td>(b)</td><td>dV/dh=8h; dh/dt=(−0.08)/(8×0.6)=−0.01667≈−0.02m/hour. Award for derivative, chain rule and value.</td><td>3</td></tr><tr><td>(c)</td><td>dV/dt=8h(dh/dt)=−0.08 gives the required equation.</td><td>1</td></tr><tr><td>(d)</td><td>Separates h dh=−0.01dt, integrates½h²=−0.01t+C. Initially h=1/√2, so C=¼. Hence h=√(0.5−0.02t),0≤t≤25. Award for separation, integration, initial condition and rule/domain.</td><td>4</td></tr></tbody></table>","diagram":"<img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\">","marks":10,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-APPLICATIONS-2023-FREE-Q06":{"question":"<p>The project digraph gives tasks A5,B9,C7,D6,E8,F4,G4,H7,J6,K9,L6,M5 in hours.</p>","parts":[{"label":"(a)","text":"<p>Complete the immediate-predecessor table.</p><table><tr><th>Task</th><th>Hours</th><th>Immediate predecessors</th></tr><tr><td>A</td><td>5</td><td></td></tr><tr><td>B</td><td>9</td><td></td></tr><tr><td>C</td><td>7</td><td></td></tr><tr><td>D</td><td>6</td><td></td></tr><tr><td>E</td><td>8</td><td></td></tr><tr><td>F</td><td>4</td><td></td></tr><tr><td>G</td><td>4</td><td></td></tr><tr><td>H</td><td>7</td><td></td></tr><tr><td>J</td><td>6</td><td></td></tr><tr><td>K</td><td>9</td><td></td></tr><tr><td>L</td><td>6</td><td></td></tr><tr><td>M</td><td>5</td><td></td></tr></table>","marks":3,"lines":9,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Show workings for critical path and minimum time.</p>","marks":3,"lines":9,"space":"lines","diagram":""},{"label":"(c)","text":"<p>Which tasks have exactly2hours float?</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(d)","text":"<p>Why may D be delayed6hours without delaying the project?</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(e)","text":"<p>Redraw the network if G is removed; task times need not be shown.</p>","marks":2,"lines":8,"space":"drawing","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>A,B,C none; D:A; E:A; F:C; G:B,E,F; H:D; J:G; K:G; L:H,J; M:D,K. Award for ten correct tasks, M and all correct.</td><td>3</td></tr><tr><td>(b)</td><td>Forward pass gives earliest node times0,5,7,13,11,17,23,26,31. Critical path A–E–G–K–M,31hours. Award for systematic working, path and duration.</td><td>3</td></tr><tr><td>(c)</td><td>C,F,J,L; award for two and then all four.</td><td>2</td></tr><tr><td>(d)</td><td>D is non-critical and has7hours total float, so6hours delay remains within its allowance.</td><td>2</td></tr><tr><td>(e)</td><td>Remove G and merge its start and end event so J and K retain predecessors B,E,F. Preserve the other tasks, including the dummy dependency from D to M.</td><td>2</td></tr></tbody></table>","diagram":"<img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\">","marks":12,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-SPECIALIST-2024-FREE-Q08":{"question":"<p>f(x)=(4/π)arccos(−x/2),−2≤x≤2, is graphed.</p>","parts":[{"label":"(a)","text":"<p>Explain why its inverse exists.</p>","marks":1,"lines":4,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Determine its inverse rule.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(c)","text":"<p>Sketch the inverse on the same axes.</p>","marks":2,"lines":8,"space":"drawing","diagram":""},{"label":"(d)","text":"<p>Use implicit differentiation to show f′(x)=4/[π√(4−x²)].</p>","marks":5,"lines":15,"space":"lines","diagram":""},{"label":"(e)","text":"<p>The shaded region lies below y=1 and above y=1/√(4−x²), between the y-axis and their intersection. Find its exact area.</p>","marks":3,"lines":9,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>It is one-to-one, passing the horizontal line test.</td><td>1</td></tr><tr><td>(b)</td><td>Interchanges variables and takes cosine: f<sup>−1</sup>(x)=−2cos(πx/4),0≤x≤4.</td><td>2</td></tr><tr><td>(c)</td><td>Reflects in y=x and includes(0,−2),(2,0),(4,2).</td><td>2</td></tr><tr><td>(d)</td><td>From cos(πy/4)=−x/2, obtains −sin(πy/4)(π/4)y′=−½. Uses sin(πy/4)=√(1−x²/4) on the stated range and simplifies to4/[π√(4−x²)]. Award for equivalent equation, chain rule, rearrangement, identity and simplification.</td><td>5</td></tr><tr><td>(e)</td><td>Intersection x=√3. Area=∫<sub>0</sub><sup>√3</sup>[1−1/√(4−x²)]dx=√3−π/3. Award for bound, integral and exact result.</td><td>3</td></tr></tbody></table>","diagram":"<img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\"><img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\">","marks":13,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-METHODS-2021-FREE-Q02":{"question":"<p>Nahyun’s school journey is uniform between15and40minutes. She normally leaves at8am. X is arrival time in minutes after8am.</p>","parts":[{"label":"(a)","text":"<p>Name the distribution.</p>","marks":1,"lines":4,"space":"lines","diagram":""},{"label":"(b)(i)","text":"<p>Find p,q,k in the density diagram.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(b)(ii)","text":"<p>Find E(X).</p>","marks":1,"lines":4,"space":"lines","diagram":""},{"label":"(b)(iii)","text":"<p>Find P(arriving before8.25am).</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(c)","text":"<p>Given she arrives by8.28am, find P(arriving after8.25am).</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(d)","text":"<p>When should she leave to be late after8.28am at most4%of the time?</p>","marks":2,"lines":6,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>Uniform.</td><td>1</td></tr><tr><td>(b)(i)</td><td>p=15,q=40,k=1/25.</td><td>2</td></tr><tr><td>(b)(ii)</td><td>27.5minutes.</td><td>1</td></tr><tr><td>(b)(iii)</td><td>(25−15)/25=0.4.</td><td>2</td></tr><tr><td>(c)</td><td>P(25&lt;X≤28)/P(X≤28)=3/13.</td><td>2</td></tr><tr><td>(d)</td><td>96th-percentile journey=15+0.96×25=39minutes; leave by7.49am.</td><td>2</td></tr></tbody></table>","diagram":"<img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\">","marks":10,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-APPLICATIONS-2019-ASSUMED-Q15":{"question":"<p>Directed power-transfer capacities are shown in kV, with two cuts and a proposed flow.</p>","parts":[{"label":"(a)","text":"<p>State both cut capacities.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Find the initial flow in Diagram2.</p>","marks":1,"lines":4,"space":"lines","diagram":""},{"label":"(c)","text":"<p>Find x,y,z in Diagram2.</p>","marks":3,"lines":9,"space":"lines","diagram":""},{"label":"(d)","text":"<p>Determine the maximum flow in the original network.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(e)","text":"<p>Engineers propose either E→T or D→G, each with capacity3kV. Which increases maximum flow? Justify.</p>","marks":3,"lines":9,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>Cut1=58; Cut2=62kV.</td><td>2</td></tr><tr><td>(b)</td><td>25+29=54kV.</td><td>1</td></tr><tr><td>(c)</td><td>x=1,y=5,z=20; one mark each.</td><td>3</td></tr><tr><td>(d)</td><td>A minimum cut through HT,HG,AF has capacity56; a feasible flow attains56kV.</td><td>2</td></tr><tr><td>(e)</td><td>Either proposal increases flow by2kV to58. E→T allows extra PB–C–E–T flow; D→G permits PB–D–G–T. Cut1 remains58, preventing any larger increase. Award for both routes and the limiting cut.</td><td>3</td></tr></tbody></table>","diagram":"<img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\"><img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\">","marks":11,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-APPLICATIONS-2019-ASSUMED-Q09":{"question":"<p>Corbie and Grant save$7000 initially plus$800month-end at2.6%p.a., compounded monthly. An apartment costs$280000 plus$22000fees; a20%deposit is required.</p>","parts":[{"label":"(a)","text":"<p>Find the account value after2years.</p>","marks":3,"lines":9,"space":"lines","diagram":""},{"label":"(b)(i)","text":"<p>Show required deposit is$60400.</p>","marks":1,"lines":4,"space":"lines","diagram":""},{"label":"(b)(ii)","text":"<p>How long until they save this deposit?</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(c)","text":"<p>Parents add$10000at the end of year2. Find the minimum subsequent monthly saving needed to have$60400by the end of year4.</p>","marks":3,"lines":9,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>Uses j=0.026/12,24payments; FV=7000(1+j)<sup>24</sup>+800[(1+j)<sup>24</sup>−1]/j≈$27059.30. Award for rate/periods, formula and value.</td><td>3</td></tr><tr><td>(b)(i)</td><td>0.20(280000+22000)=$60400.</td><td>1</td></tr><tr><td>(b)(ii)</td><td>Solves the annuity equation for months; first whole month62, or5years2months.</td><td>2</td></tr><tr><td>(c)</td><td>Starts remaining24months at$37059.30; solves60400=37059.30(1+j)<sup>24</sup>+R[(1+j)<sup>24</sup>−1]/j. R≈$868.23/month rounding upward. Award for balance, equation and payment.</td><td>3</td></tr></tbody></table>","diagram":"","marks":9,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-METHODS-2018-ASSUMED-Q18":{"question":"<p>Sound level is L=10log₁₀(I/I₀)dB, with intensities in W/m².</p>","parts":[{"label":"(a)","text":"<p>Find L when I=5×10<sup>9</sup>I₀.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(b)","text":"<p>I=10<sup>−5</sup>W/m² corresponds to70dB. Determine I₀.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(c)","text":"<p>Rainfall averages50dB and traffic85dB. How many times as intense is traffic?</p>","marks":3,"lines":9,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>10log₁₀(5×10<sup>9</sup>)≈96.99dB.</td><td>2</td></tr><tr><td>(b)</td><td>70=10log₁₀(10<sup>−5</sup>/I₀), giving I₀=10<sup>−12</sup>W/m².</td><td>2</td></tr><tr><td>(c)</td><td>Subtracts levels:35=10log₁₀(I<sub>traffic</sub>/I<sub>rain</sub>); ratio=10<sup>3.5</sup>≈3162.28. Award for difference, log equation and ratio.</td><td>3</td></tr></tbody></table>","diagram":"","marks":7,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-METHODS-2021-ASSUMED-Q09":{"question":"<p>A building’s height is h(x)=4sin(x−3π/2)−x²+3πx−4metres,0≤x≤W, with the cross-section shown.</p>","parts":[{"label":"(a)","text":"<p>Find width W to the nearest centimetre.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Determine h′(x).</p>","marks":1,"lines":4,"space":"lines","diagram":""},{"label":"(c)","text":"<p>Find the location and value of maximum height, nearest centimetre.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(d)","text":"<p>Climbers ascend from the left ground point to the top. A rest platform is placed where the second half of the climb is steepest. Find its height, nearest centimetre.</p>","marks":3,"lines":9,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>Solves the nonzero root h(W)=0: W≈8.64m.</td><td>2</td></tr><tr><td>(b)</td><td>h′=4cos(x−3π/2)−2x+3π.</td><td>1</td></tr><tr><td>(c)</td><td>Maximum at x≈5.74m, height≈20.57m.</td><td>2</td></tr><tr><td>(d)</td><td>Maximises positive slope using h″=−4sin(x−3π/2)−2=0, choosing x=4π/3 on the specified ascent. Height≈15.93m. Award for second derivative, valid location and height.</td><td>3</td></tr></tbody></table>","diagram":"<img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\">","marks":8,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-SPECIALIST-2017-ASSUMED-Q15":{"question":"<p>A model race car starts at A(3,0) on the track shown. Velocity is v(t)=(−sin(t/3),2cos t)m/second.</p>","parts":[{"label":"(a)","text":"<p>Find and draw initial velocity.</p>","marks":2,"lines":8,"space":"drawing","diagram":""},{"label":"(b)","text":"<p>Give a vector integral for displacement change in the first3π/2seconds.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(c)","text":"<p>Determine r(t).</p>","marks":3,"lines":9,"space":"lines","diagram":""},{"label":"(d)","text":"<p>At the sharp point B at the top of the first lobe, speed is minimal. Find acceleration there to0.01.</p>","marks":3,"lines":9,"space":"lines","diagram":""},{"label":"(e)","text":"<p>Find one-lap distance to0.01m.</p>","marks":3,"lines":9,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>v(0)=(0,2); draws upward vector at A.</td><td>2</td></tr><tr><td>(b)</td><td>Δr=∫<sub>0</sub><sup>3π/2</sup>(−sin(t/3),2cos t)dt.</td><td>2</td></tr><tr><td>(c)</td><td>Integrates components and uses A: r(t)=(3cos(t/3),2sin t). Award for integration and initial constants.</td><td>3</td></tr><tr><td>(d)</td><td>B is reached at t=π/2. a(t)=(−⅓cos(t/3),−2sin t), so a(B)≈(−0.29,−2.00)m/second². Award for time, derivative and components.</td><td>3</td></tr><tr><td>(e)</td><td>One lap takes6πseconds; distance=∫<sub>0</sub><sup>6π</sup>√[sin²(t/3)+4cos²t]dt≈28.16m. Award for period, speed integral and value.</td><td>3</td></tr></tbody></table>","diagram":"<img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\">","marks":13,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-METHODS-2024-FREE-Q02":{"question":"<p>A screen graphic has position x(t)=t³/3−7t²+40tcm,0≤t≤15seconds.</p>","parts":[{"label":"(a)","text":"<p>Find initial velocity.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Is it initially speeding up or slowing down? Justify.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(c)","text":"<p>Evaluate ∫<sub>3</sub><sup>9</sup>v(t)dt and interpret it.</p>","marks":3,"lines":9,"space":"lines","diagram":""},{"label":"(d)","text":"<p>Find total distance over the15seconds.</p>","marks":3,"lines":9,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>v=t²−14t+40, hence v(0)=40cm/second.</td><td>2</td></tr><tr><td>(b)</td><td>a=2t−14, so initial acceleration−14 opposes positive velocity; slowing down.</td><td>2</td></tr><tr><td>(c)</td><td>x(9)−x(3)=36−66=−30cm: net displacement from3to9seconds. Award for theorem, value and interpretation.</td><td>3</td></tr><tr><td>(d)</td><td>v=(t−4)(t−10); split at4and10. Distance=x(4)−x(0)+x(4)−x(10)+x(15)−x(10)=222cm. Award for turns, signed-distance sum and result.</td><td>3</td></tr></tbody></table>","diagram":"","marks":10,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-SPECIALIST-2018-ASSUMED-Q12":{"question":"<p>Device lifetimes have exponential mean20years and SD20years. A random sample of50 has mean X̄.</p>","parts":[{"label":"(a)","text":"<p>State and justify the approximate distribution of X̄.</p>","marks":3,"lines":9,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Find P(15≤X̄≤25).</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(c)","text":"<p>If lifetimes instead have a different distribution with the same mean and SD, does(b)change? Explain.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(d)","text":"<p>For samples of n, P(X̄&gt;25)=0.03. Determine n.</p>","marks":4,"lines":12,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>By the central limit theorem, approximately normal with mean20 and variance400/50=8. Award for normality, parameters and justification.</td><td>3</td></tr><tr><td>(b)</td><td>Standardises to±5/√8; probability≈0.9229.</td><td>2</td></tr><tr><td>(c)</td><td>No material change to the approximation if samples remain independent and sufficiently large; CLT uses the same population mean and variance.</td><td>2</td></tr><tr><td>(d)</td><td>(25−20)/(20/√n)=Φ<sup>−1</sup>(0.97)≈1.88079; n≈56.60, so about57devices. Award for tail quantile, equation, solution and whole sample size.</td><td>4</td></tr></tbody></table>","diagram":"","marks":11,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-APPLICATIONS-2017-ASSUMED-Q10":{"question":"<p>A laboratory starts with400bacteria, growing35%weekly.</p>","parts":[{"label":"(a)","text":"<p>Select correct models:400(1.35)<sup>t</sup>;400(0.35)<sup>t</sup>;540(1.35)<sup>t−1</sup>;540(1.35)<sup>t+1</sup>.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Find population after3weeks.</p>","marks":1,"lines":4,"space":"lines","diagram":""},{"label":"(c)","text":"<p>During which week does it first reach1800?</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(d)","text":"<p>After8weeks growth drops to20%weekly. When does population reach15812, measured from the start?</p>","marks":3,"lines":9,"space":"lines","diagram":""},{"label":"(e)","text":"<p>Find an equivalent constant weekly growth rate over that total time.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(f)","text":"<p>At15812, bacteria begin dying at250per day. About how many weeks until none remain?</p>","marks":2,"lines":6,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>First and third models are equivalent and correct.</td><td>2</td></tr><tr><td>(b)</td><td>400(1.35)³≈984bacteria.</td><td>1</td></tr><tr><td>(c)</td><td>Solves400(1.35)<sup>t</sup>=1800, t≈5.01; during week6.</td><td>2</td></tr><tr><td>(d)</td><td>Population after8weeks=400(1.35)<sup>8</sup>. Solves this times1.2<sup>s</sup>=15812, giving s≈7; total15weeks. Award for intermediate population, equation and total.</td><td>3</td></tr><tr><td>(e)</td><td>g=(15812/400)<sup>1/15</sup>−1≈27.78%weekly.</td><td>2</td></tr><tr><td>(f)</td><td>15812/(250×7)≈9.04weeks.</td><td>2</td></tr></tbody></table>","diagram":"","marks":12,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-METHODS-2022-FREE-Q04":{"question":"<p>The supplied graph is f(x)=log₂x.</p>","parts":[{"label":"(a)(i)","text":"<p>Use the graph to solve log₂(x−5)=3.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(a)(ii)","text":"<p>Use the graph to estimate √7 to one decimal place. Hint: let x=√7.</p>","marks":3,"lines":9,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Determine the translated function g shown.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(c)(i)","text":"<p>Show log₂[1/(x−1)]=−log₂(x−1).</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(c)(ii)","text":"<p>Sketch h(x)=log₂[1/(x−1)].</p>","marks":3,"lines":9,"space":"drawing","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)(i)</td><td>Reads x−5=8, hence x=13.</td><td>2</td></tr><tr><td>(a)(ii)</td><td>log₂√7=½log₂7≈1.4; inverse graph reading gives√7≈2.6. Award for log law and both readings.</td><td>3</td></tr><tr><td>(b)</td><td>Vertical translation3units up: g(x)=log₂x+3.</td><td>2</td></tr><tr><td>(c)(i)</td><td>Uses log₂1−log₂(x−1), with log₂1=0.</td><td>2</td></tr><tr><td>(c)(ii)</td><td>Vertical asymptote x=1; passes(2,0),(3,−1); correct decreasing log shape on x&gt;1. One mark per feature.</td><td>3</td></tr></tbody></table>","diagram":"<img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\"><img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\"><img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\">","marks":12,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-SPECIALIST-2016-ASSUMED-Q20":{"question":"<p>A mirror plane is r·(0,1,2)=9. A laser starts at S=(−2,3,6) and points along d₁=(1,1,−1), meeting the mirror at B. Incident and reflected rays make equal angles with the normal and lie in the same plane.</p>","parts":[{"label":"(a)","text":"<p>Determine B.</p>","marks":4,"lines":12,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Determine the reflected unit direction d₂, components to0.01.</p>","marks":3,"lines":9,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>Ray r=(−2,3,6)+λ(1,1,−1). Substitute y+2z=9:15−λ=9, so λ=6; B=(4,9,0). Award for ray, substitution, parameter and point.</td><td>4</td></tr><tr><td>(b)</td><td>Reflects d₁ in the mirror using d₂(unscaled)=d₁−2(d₁·n)n/|n|²=(1,1.4,−0.2). Normalises by√3 to give≈(0.58,0.81,−0.12). Award for reflection, direction and normalisation.</td><td>3</td></tr></tbody></table>","diagram":"<img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\">","marks":7,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-METHODS-2019-ASSUMED-Q11":{"question":"<p>Pizza delivery time T is normal with mean25minutes and SD2minutes. Deliveries after30minutes are free.</p>","parts":[{"label":"(a)","text":"<p>Find the free-delivery probability.</p>","marks":1,"lines":4,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Among50independent orders, find the probability more than3are free.</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(c)","text":"<p>With the same distribution, what advertised time reduces free deliveries to0.1%?</p>","marks":2,"lines":6,"space":"lines","diagram":""},{"label":"(d)","text":"<p>If the mean remains25 and the advertised time30, what SD makes free deliveries0.1%?</p>","marks":3,"lines":9,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>P(T&gt;30)=P(Z&gt;2.5)≈0.006210.</td><td>1</td></tr><tr><td>(b)</td><td>X~Bin(50,0.0062097); P(X&gt;3)≈0.0002726.</td><td>2</td></tr><tr><td>(c)</td><td>25+2Φ<sup>−1</sup>(0.999)≈31.18minutes.</td><td>2</td></tr><tr><td>(d)</td><td>(30−25)/σ=Φ<sup>−1</sup>(0.999)≈3.09023, so σ≈1.618minutes. Award for quantile, equation and SD.</td><td>3</td></tr></tbody></table>","diagram":"","marks":8,"responseLines":0,"reviewedAgainstSource":true},"WV-MATHS-APPLICATIONS-2020-ASSUMED-Q13":{"question":"<p>A road network links warehouse A to seven retail outlets. Edge lengths are kilometres.</p>","parts":[{"label":"(a)","text":"<p>State the shortest Hamiltonian path from A and its length.</p>","marks":3,"lines":9,"space":"lines","diagram":""},{"label":"(b)","text":"<p>Find the shortest A-to-H route and distance, showing a suitable network method.</p>","marks":3,"lines":9,"space":"lines","diagram":""},{"label":"(c)","text":"<p>By how much must road CH be shortened for the shortest A-to-H route to use CH?</p>","marks":3,"lines":9,"space":"lines","diagram":""}],"answer":"<table class=\"editable-source-table\"><thead><tr><th>Part</th><th>Solution and marking criterion</th><th>Marks</th></tr></thead><tbody><tr><td>(a)</td><td>A–D–C–B–E–G–H–F, length14+10+8+12+10+6+10=70km. Award for Hamiltonian route, optimum and length.</td><td>3</td></tr><tr><td>(b)</td><td>Uses a shortest-path labelling method; A–C–F–H has distance44km. Award for workings, route and length.</td><td>3</td></tr><tr><td>(c)</td><td>A–C–H has length22+CH; it must beat44km, so CH&lt;22km. From its original26km, reduction x must satisfy4&lt;x&lt;26km. Award for comparison, inequality and reduction.</td><td>3</td></tr></tbody></table>","diagram":"<img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\"><img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\"><img src=\"data:image/webp;base64,\" alt=\"Original examination graph or diagram\" data-word-max-height=\"3.2\">","marks":9,"responseLines":0,"reviewedAgainstSource":true}});
